fn run_search(opts: Options) -> i32 {
    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());

    let results = walk::collect_results(&opts);

    if opts.quiet {
        return if results.is_empty() { 1 } else { 0 };
    }

    if !opts.exec_cmds.is_empty() {
        exec::run_exec(&results, &opts);
        return 0;
    }

    if opts.exec_batch_cmds.is_empty() {
        // Just output
        output_results(&results, &opts, &mut out);
    } else {
        exec::run_exec_batch(&results, &opts);
    }
    0
}

fn output_results<W: Write>(results: &[PathBuf], opts: &Options, out: &mut W) {
    if opts.list_details {
        // Use ls -ld
        let paths: Vec<String> = results.iter()
            .map(|p| p.to_string_lossy().into_owned())
            .collect();
        if !paths.is_empty() {
            let status = Command::new("ls")
                .args(["-ld", "--color=auto"])
                .args(&paths)
                .status();
        }
        return;
    }

    let use_color = match opts.color {
        ColorMode::Always => true,
        ColorMode::Never => false,
        ColorMode::Auto => is_tty(),
    };

    let ls_colors = if use_color {
        ls_colors::LsColors::from_env()
    } else {
        ls_colors::LsColors::empty()
    };

    for path in results {
        format_and_print(path, opts, &ls_colors, out);
    }
}

fn format_and_print<W: Write>(path: &Path, opts: &Options, ls_colors: &ls_colors::LsColors, out: &mut W) {
    let path_str = if let Some(ref fmt) = opts.format {
        apply_format(fmt, path)
    } else {
        path_to_display(path, opts)
    };

    let use_color = match opts.color {
        ColorMode::Always => true,
        ColorMode::Never => false,
        ColorMode::Auto => is_tty(),
    };

    if use_color {
        let colored = ls_colors.colorize(path, &path_str);
        if opts.print0 {
            write!(out, "{}\0", colored).ok();
        } else {
            writeln!(out, "{}", colored).ok();
        }
    } else {
        if opts.print0 {
            write!(out, "{}\0", path_str).ok();
        } else {
            writeln!(out, "{}", path_str).ok();
        }
    }
}

fn path_to_display(path: &Path, opts: &Options) -> String {
    path.to_string_lossy().into_owned()
}

fn apply_format(fmt: &str, path: &Path) -> String {
    let path_str = path.to_string_lossy();
    let basename = path.file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_default();
    let parent = path.parent()
        .map(|p| p.to_string_lossy().into_owned())
        .unwrap_or_else(|| ".".to_string());
    let path_no_ext = {
        let s = path_str.as_ref();
        if let Some(pos) = s.rfind('.') {
            if pos > s.rfind('/').map(|p| p + 1).unwrap_or(0) {
                s[..pos].to_string()
            } else {
                s.to_string()
            }
        } else {
            s.to_string()
        }
    };
    let basename_no_ext = {
        if let Some(pos) = basename.rfind('.') {
            if pos > 0 {
                basename[..pos].to_string()
            } else {
                basename.clone()
            }
        } else {
            basename.clone()
        }
    };

    let mut result = String::new();
    let chars: Vec<char> = fmt.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '{' {
            if i + 1 < chars.len() && chars[i + 1] == '{' {
                result.push('{');
                i += 2;
                continue;
            }
            // Find closing }
            let start = i;
            let mut j = i + 1;
            while j < chars.len() && chars[j] != '}' {
                j += 1;
            }
            if j < chars.len() {
                let placeholder: String = chars[i+1..j].iter().collect();
                match placeholder.as_str() {
                    "" => result.push_str(&path_str),
                    "/" => result.push_str(&basename),
                    "//" => result.push_str(&parent),
                    "." => result.push_str(&path_no_ext),
                    "/." => result.push_str(&basename_no_ext),
                    _ => {
                        result.push('{');
                        result.push_str(&placeholder);
                        result.push('}');
                    }
                }
                i = j + 1;
            } else {
                result.push(chars[i]);
                i += 1;
            }
        } else if chars[i] == '}' && i + 1 < chars.len() && chars[i + 1] == '}' {
            result.push('}');
            i += 2;
        } else {
            result.push(chars[i]);
            i += 1;
        }
    }
    result
}

fn is_tty() -> bool {
    unsafe { libc_isatty(1) }
}

extern "C" {
    fn isatty(fd: i32) -> i32;
}

fn libc_isatty(fd: i32) -> bool {
    unsafe { isatty(fd) != 0 }
}

