        }
        "hyperlink" => {
            match val.as_str() {
                "auto" => opts.hyperlink = HyperlinkMode::Auto,
                "always" => opts.hyperlink = HyperlinkMode::Always,
                "never" => opts.hyperlink = HyperlinkMode::Never,
                _ => return Some(format!("invalid value '{}' for '--hyperlink'", val)),
            }
        }
        "ignore-contain" => {
            opts.ignore_contain.push(val);
        }
        "threads" => {
            match val.parse::<usize>() {
                Ok(v) => opts.threads = Some(v),
                Err(_) => return Some(format!("invalid value '{}' for '--threads'", val)),
            }
        }
        "max-results" => {
            match val.parse::<usize>() {
                Ok(v) => opts.max_results = Some(v),
                Err(_) => return Some(format!("invalid value '{}' for '--max-results'", val)),
            }
        }
        "base-directory" => {
            opts.base_directory = Some(std::path::PathBuf::from(val));
        }
        "path-separator" => {
            opts.path_separator = Some(val);
        }
        "search-path" => {
            opts.search_path_extra.push(std::path::PathBuf::from(val));
        }
        "and" => {
            opts.and_patterns.push(val);
        }
        "strip-cwd-prefix" => {
            match val.as_str() {
                "auto" => opts.strip_cwd_prefix = StripCwdPrefix::Auto,
                "always" => opts.strip_cwd_prefix = StripCwdPrefix::Always,
                "never" => opts.strip_cwd_prefix = StripCwdPrefix::Never,
                _ => return Some(format!("invalid value '{}' for '--strip-cwd-prefix'", val)),
            }
        }
        "unrestricted" => {
            opts.hidden = true;
            opts.no_ignore = true;
        }
        _ => {}
    }
    None
}

fn parse_file_type(s: &str) -> Option<FileType> {
    match s {
        "f" | "file" => Some(FileType::File),
        "d" | "dir" | "directory" => Some(FileType::Directory),
        "l" | "symlink" => Some(FileType::Symlink),
        "x" | "executable" => Some(FileType::Executable),
        "e" | "empty" => Some(FileType::Empty),
        "s" | "socket" => Some(FileType::Socket),
        "p" | "pipe" => Some(FileType::Pipe),
        "b" | "block-device" => Some(FileType::BlockDevice),
        "c" | "char-device" => Some(FileType::CharDevice),
        _ => None,
    }
}

fn parse_size_filter(s: &str) -> Result<SizeFilter, String> {
    let s = s.trim();
    let (cmp, rest) = if s.starts_with('+') {
        (SizeCmp::Plus, &s[1..])
    } else if s.starts_with('-') {
        (SizeCmp::Minus, &s[1..])
    } else {
        (SizeCmp::Equal, s)
    };

    // Find where digits end
    let num_end = rest.find(|c: char| !c.is_ascii_digit()).unwrap_or(rest.len());
    if num_end == 0 {
        return Err(format!("invalid size filter: {}", s));
    }
    let num: u64 = rest[..num_end].parse().map_err(|_| format!("invalid size: {}", s))?;
    let unit = rest[num_end..].trim().to_lowercase();

    let bytes = match unit.as_str() {
        "b" | "" => num,
        "k" => num * 1000,
        "m" => num * 1_000_000,
        "g" => num * 1_000_000_000,
        "t" => num * 1_000_000_000_000,
        "ki" => num * 1024,
        "mi" => num * 1024 * 1024,
        "gi" => num * 1024 * 1024 * 1024,
        "ti" => num * 1024 * 1024 * 1024 * 1024,
        _ => return Err(format!("unknown size unit: {}", unit)),
    };

    Ok(SizeFilter { cmp, bytes })
}

fn parse_owner_filter(s: &str) -> Result<OwnerFilter, String> {
    let (exclude, s) = if s.starts_with('!') {
        (true, &s[1..])
    } else {
        (false, s)
    };

    if let Some(colon_pos) = s.find(':') {
        let user_str = &s[..colon_pos];
        let group_str = &s[colon_pos+1..];

        let user = if user_str.is_empty() {
            None
        } else {
            Some(parse_owner_spec(user_str)?)
        };

        let group = if group_str.is_empty() {
            None
        } else {
            Some(parse_owner_spec(group_str)?)
        };

        Ok(OwnerFilter { user, group, exclude })
    } else {
        let user = Some(parse_owner_spec(s)?);
        Ok(OwnerFilter { user, group: None, exclude })
    }
}

fn parse_owner_spec(s: &str) -> Result<OwnerSpec, String> {
    if let Ok(id) = s.parse::<u32>() {
        Ok(OwnerSpec { by_name: None, by_id: Some(id) })
    } else {
        Ok(OwnerSpec { by_name: Some(s.to_string()), by_id: None })
    }
}
