pub fn parse(args: Vec<String>) -> ParseResult {
    let mut opts = Options::default();
    let mut positional: Vec<String> = Vec::new();
    let mut i = 1usize;
    let n = args.len();

    // Check for NO_COLOR
    if std::env::var("NO_COLOR").is_ok() {
        opts.color = ColorMode::Never;
    }

    let mut after_dash_dash = false;

    while i < n {
        let arg = &args[i];

        if after_dash_dash {
            positional.push(arg.clone());
            i += 1;
            continue;
        }

        if arg == "--" {
            after_dash_dash = true;
            i += 1;
            continue;
        }

        if arg.starts_with("--") {
            let long = &arg[2..];
            match long {
                "hidden" | "no-hidden" => {
                    opts.hidden = long == "hidden";
                    i += 1;
                }
                "no-ignore" | "ignore" => {
                    opts.no_ignore = long == "no-ignore";
                    i += 1;
                }
                "no-ignore-vcs" | "ignore-vcs" => {
                    opts.no_ignore_vcs = long == "no-ignore-vcs";
                    i += 1;
                }
                "no-require-git" | "require-git" => {
                    opts.no_require_git = long == "no-require-git";
                    i += 1;
                }
                "no-ignore-parent" => {
                    opts.no_ignore_parent = true;
                    i += 1;
                }
                "case-sensitive" => {
                    opts.case_sensitive = true;
                    opts.ignore_case = false;
                    i += 1;
                }
                "ignore-case" => {
                    opts.ignore_case = true;
                    opts.case_sensitive = false;
                    i += 1;
                }
                "glob" => {
                    opts.glob = true;
                    opts.regex_mode = false;
                    i += 1;
                }
                "regex" => {
                    opts.regex_mode = true;
                    opts.glob = false;
                    i += 1;
                }
                "fixed-strings" => {
                    opts.fixed_strings = true;
                    i += 1;
                }
                "absolute-path" | "relative-path" => {
                    opts.absolute_path = long == "absolute-path";
                    i += 1;
                }
                "list-details" => {
                    opts.list_details = true;
                    i += 1;
                }
                "follow" | "no-follow" => {
                    opts.follow_links = long == "follow";
                    i += 1;
                }
                "full-path" => {
                    opts.full_path = true;
                    i += 1;
                }
                "print0" => {
                    opts.print0 = true;
                    i += 1;
                }
                "prune" => {
                    opts.prune = true;
                    i += 1;
                }
                "quiet" | "has-results" => {
                    opts.quiet = true;
                    i += 1;
                }
                "show-errors" => {
                    opts.show_errors = true;
                    i += 1;
                }
                "one-file-system" => {
                    opts.one_file_system = true;
                    i += 1;
                }
                "help" => return ParseResult::Help(true),
                "version" => return ParseResult::Version,
                _ => {
                    // Handle --key=value or --key value forms
                    if let Some(eq_pos) = long.find('=') {
                        let key = &long[..eq_pos];
                        let val = long[eq_pos+1..].to_string();
                        match parse_long_with_value(key, val, &mut opts) {
                            Some(e) => return ParseResult::Error(e),
                            None => {}
                        }
                        i += 1;
                    } else {
                        // Next arg is value
                        let key = long;
                        // Some flags take optional values (like --hyperlink --strip-cwd-prefix)
                        let takes_opt_value = matches!(key, "hyperlink" | "strip-cwd-prefix");
                        let takes_value = matches!(key,
                            "max-depth" | "min-depth" | "exact-depth" |
                            "type" | "t" |
                            "extension" | "exclude" |
                            "size" |
                            "changed-within" | "changed-before" |
                            "change-newer-than" | "change-older-than" | "newer" | "older" | "changed-after" |
                            "owner" |
                            "format" |
                            "exec" | "exec-batch" |
                            "batch-size" |
                            "ignore-file" |
                            "color" |
                            "ignore-contain" |
                            "threads" |
                            "max-results" |
                            "base-directory" |
                            "path-separator" |
                            "search-path" |
                            "and" |
                            "unrestricted"
                        );
                        if takes_opt_value {
                            // Check if next arg looks like a value for this option
                            let next = args.get(i + 1).map(|s| s.as_str());
                            let val = if next.map(|s| !s.starts_with('-')).unwrap_or(false) {
                                let v = next.unwrap().to_string();
                                i += 1;
                                v
                            } else {
                                "auto".to_string()
                            };
                            match parse_long_with_value(key, val, &mut opts) {
                                Some(e) => return ParseResult::Error(e),
                                None => {}
                            }
                            i += 1;
                        } else if takes_value {
                            i += 1;
                            // Handle exec/exec-batch specially
                            if key == "exec" || key == "exec-batch" {
                                let (cmd, consumed) = collect_exec_args(&args, i);
                                if key == "exec" {
                                    opts.exec_cmds.push(ExecCommand { args: cmd });
                                } else {
                                    opts.exec_batch_cmds.push(ExecCommand { args: cmd });
                                }
                                i += consumed;
                                continue;
                            }
                            if i >= n {
                                return ParseResult::Error(format!("option '--{}' requires an argument", key));
                            }
                            let val = args[i].clone();
                            match parse_long_with_value(key, val, &mut opts) {
                                Some(e) => return ParseResult::Error(e),
                                None => {}
                            }
                            i += 1;
                        } else {
                            return ParseResult::Error(format!("error: unexpected argument '--{}' found", long));
                        }
                    }
                }
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            // Short flags
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut ci = 0;
            while ci < chars.len() {
                let c = chars[ci];
                match c {
                    'H' => { opts.hidden = true; ci += 1; }
                    'I' => { opts.no_ignore = true; ci += 1; }
                    'u' => {
                        opts.hidden = true;
                        opts.no_ignore = true;
                        ci += 1;
                    }
                    's' => { opts.case_sensitive = true; opts.ignore_case = false; ci += 1; }
                    'i' => { opts.ignore_case = true; opts.case_sensitive = false; ci += 1; }
                    'g' => { opts.glob = true; opts.regex_mode = false; ci += 1; }
                    'F' => { opts.fixed_strings = true; ci += 1; }
                    'a' => { opts.absolute_path = true; ci += 1; }
                    'l' => { opts.list_details = true; ci += 1; }
                    'L' => { opts.follow_links = true; ci += 1; }
                    'p' => { opts.full_path = true; ci += 1; }
                    '0' => { opts.print0 = true; ci += 1; }
                    'q' => { opts.quiet = true; ci += 1; }
                    '1' => { opts.max_results = Some(1); ci += 1; }
                    'h' => return ParseResult::Help(false),
                    'V' => return ParseResult::Version,
                    'C' => {
                        // rest of chars or next arg
                        ci += 1;
                        let val = if ci < chars.len() {
                            let v: String = chars[ci..].iter().collect();
                            ci = chars.len();
                            v
                        } else {
                            i += 1;
                            if i >= n { return ParseResult::Error("option '-C' requires an argument".to_string()); }
                            args[i].clone()
                        };
                        opts.base_directory = Some(std::path::PathBuf::from(val));
                    }
                    'd' | 'E' | 't' | 'e' | 'S' | 'o' | 'x' | 'X' | 'c' | 'j' => {
                        ci += 1;
                        let val = if ci < chars.len() {
                            let v: String = chars[ci..].iter().collect();
                            ci = chars.len();
                            v
                        } else {
                            i += 1;
                            if i >= n { return ParseResult::Error(format!("option '-{}' requires an argument", c)); }
                            args[i].clone()
                        };
                        match c {
                            'd' => {
                                match val.parse::<usize>() {
                                    Ok(v) => opts.max_depth = Some(v),
                                    Err(_) => return ParseResult::Error(format!("invalid value '{}' for '--max-depth'", val)),
                                }
                            }
                            'E' => {
                                opts.exclude_patterns.push(val);
                            }
                            't' => {
                                match parse_file_type(&val) {
                                    Some(ft) => opts.file_types.push(ft),
                                    None => return ParseResult::Error(format!("unknown type filter: {}", val)),
                                }
                            }
                            'e' => {
                                opts.extensions.push(val.trim_start_matches('.').to_lowercase());
                            }
                            'S' => {
                                match parse_size_filter(&val) {
                                    Ok(sf) => opts.size_filters.push(sf),
                                    Err(e) => return ParseResult::Error(e),
                                }
                            }
                            'o' => {
                                match parse_owner_filter(&val) {
                                    Ok(of) => opts.owner_filter = Some(of),
                                    Err(e) => return ParseResult::Error(e),
                                }
                            }
                            'x' => {
                                // We need to collect remaining args
                                // First get the initial command
                                let start_i = i;
                                let mut cmd_args = vec![val];
                                i += 1;
                                while i < n {
                                    if args[i] == ";" {
                                        i += 1;
                                        break;
                                    }
                                    // Stop if we hit something that looks like a fd option
                                    cmd_args.push(args[i].clone());
                                    i += 1;
                                }
                                opts.exec_cmds.push(ExecCommand { args: cmd_args });
                                ci = chars.len();
                                continue;
                            }
                            'X' => {
                                let mut cmd_args = vec![val];
                                i += 1;
                                while i < n {
                                    if args[i] == ";" {
                                        i += 1;
                                        break;
                                    }
                                    cmd_args.push(args[i].clone());
                                    i += 1;
                                }
                                opts.exec_batch_cmds.push(ExecCommand { args: cmd_args });
                                ci = chars.len();
                                continue;
                            }
                            'c' => {
                                match val.as_str() {
                                    "auto" => opts.color = ColorMode::Auto,
                                    "always" => opts.color = ColorMode::Always,
                                    "never" => opts.color = ColorMode::Never,
                                    _ => return ParseResult::Error(format!("invalid value '{}' for '--color'", val)),
                                }
                            }
                            'j' => {
                                match val.parse::<usize>() {
                                    Ok(v) => opts.threads = Some(v),
                                    Err(_) => return ParseResult::Error(format!("invalid value '{}' for '--threads'", val)),
                                }
                            }
                            _ => {}
                        }
                    }
                    _ => {
                        return ParseResult::Error(format!("error: unexpected argument '-{}' found", c));
                    }
                }
            }
            i += 1;
        } else {
            positional.push(arg.clone());
            i += 1;
        }
    }

    // Process positional args
    // First positional is pattern, rest are paths
    // But if no pattern and paths provided via --search-path, first positional can also be path
    let mut pos_iter = positional.into_iter();

    if opts.search_path_extra.is_empty() {
        // First positional = pattern (if any)
        if let Some(first) = pos_iter.next() {
            // Check if it looks like a path with separator and warn
            if first.contains('/') && !opts.full_path {
                // fd warns about this
                eprintln!("[fd error]: The search pattern '{}' contains a path-separation character ('/') and will not lead to any search results.\n  If you want to search for all files inside the '{}' directory, use a match-all pattern:\n    fd . '{}'\n  Instead, if you want your pattern to match the full file path, use:\n    fd --full-path '{}'", first, first, first, first);
                std::process::exit(1);
            }
            opts.pattern = Some(first);
        }
        // Remaining positionals = search paths
        for p in pos_iter {
            opts.search_paths.push(std::path::PathBuf::from(p));
        }
    } else {
        // All positionals could be paths since --search-path was used
        if let Some(first) = pos_iter.next() {
            opts.pattern = Some(first);
        }
    }

    // Merge search_path_extra into search_paths
    if !opts.search_path_extra.is_empty() {
        for p in opts.search_path_extra.clone() {
            opts.search_paths.push(p);
        }
    }

    // Apply base_directory
    if let Some(ref base) = opts.base_directory.clone() {
        if let Err(e) = std::env::set_current_dir(base) {
            return ParseResult::Error(format!("cannot change directory to '{}': {}", base.display(), e));
        }
    }

    // Default search path is current directory
    if opts.search_paths.is_empty() {
        opts.search_paths.push(std::path::PathBuf::from("."));
    }

    ParseResult::Ok(opts)
}

fn collect_exec_args(args: &[String], start: usize) -> (Vec<String>, usize) {
    let mut cmd = Vec::new();
    let mut i = start;
    while i < args.len() {
        if args[i] == ";" {
            i += 1;
            break;
        }
        cmd.push(args[i].clone());
        i += 1;
    }
    (cmd, i - start)
}

fn parse_long_with_value(key: &str, val: String, opts: &mut Options) -> Option<String> {
    match key {
        "max-depth" => {
            match val.parse::<usize>() {
                Ok(v) => opts.max_depth = Some(v),
                Err(_) => return Some(format!("invalid value '{}' for '--max-depth'", val)),
            }
        }
        "min-depth" => {
            match val.parse::<usize>() {
                Ok(v) => opts.min_depth = Some(v),
                Err(_) => return Some(format!("invalid value '{}' for '--min-depth'", val)),
            }
        }
        "exact-depth" => {
            match val.parse::<usize>() {
                Ok(v) => {
                    opts.min_depth = Some(v);
                    opts.max_depth = Some(v);
                }
                Err(_) => return Some(format!("invalid value '{}' for '--exact-depth'", val)),
            }
        }
        "exclude" => {
            opts.exclude_patterns.push(val);
        }
        "type" => {
            match parse_file_type(&val) {
                Some(ft) => opts.file_types.push(ft),
                None => return Some(format!("unknown type filter: {}", val)),
            }
        }
        "extension" => {
            opts.extensions.push(val.trim_start_matches('.').to_lowercase());
        }
        "size" => {
            match parse_size_filter(&val) {
                Ok(sf) => opts.size_filters.push(sf),
                Err(e) => return Some(e),
            }
        }
        "changed-within" | "change-newer-than" | "newer" | "changed-after" => {
            opts.changed_within = Some(val);
        }
        "changed-before" | "change-older-than" | "older" => {
            opts.changed_before = Some(val);
        }
        "owner" => {
            match parse_owner_filter(&val) {
                Ok(of) => opts.owner_filter = Some(of),
                Err(e) => return Some(e),
            }
        }
        "format" => {
            opts.format = Some(val);
        }
        "batch-size" => {
            match val.parse::<usize>() {
                Ok(v) => opts.batch_size = v,
                Err(_) => return Some(format!("invalid value '{}' for '--batch-size'", val)),
            }
        }
        "ignore-file" => {
            opts.ignore_files.push(std::path::PathBuf::from(val));
        }
        "color" => {
            match val.as_str() {
                "auto" => opts.color = ColorMode::Auto,
                "always" => opts.color = ColorMode::Always,
                "never" => opts.color = ColorMode::Never,
                _ => return Some(format!("invalid value '{}' for '--color'", val)),
            }
        }
        "hyperlink" => {
            match val.as_str() {
                "auto" => opts.hyperlink = HyperlinkMode::Auto,
                "always" => opts.hyperlink = HyperlinkMode::Always,
                "never" => opts.hyperlink = HyperlinkMode::Never,
                _ => return Some(format!("invalid value '{}' for '--hyperlink'", val)),
            }
        }
        "ignore-contain" => {
            opts.ignore_contain.push(val);
        }
        "threads" => {
            match val.parse::<usize>() {
                Ok(v) => opts.threads = Some(v),
                Err(_) => return Some(format!("invalid value '{}' for '--threads'", val)),
            }
        }
        "max-results" => {
            match val.parse::<usize>() {
                Ok(v) => opts.max_results = Some(v),
                Err(_) => return Some(format!("invalid value '{}' for '--max-results'", val)),
            }
        }
        "base-directory" => {
            opts.base_directory = Some(std::path::PathBuf::from(val));
        }
        "path-separator" => {
            opts.path_separator = Some(val);
        }
        "search-path" => {
            opts.search_path_extra.push(std::path::PathBuf::from(val));
        }
        "and" => {
            opts.and_patterns.push(val);
        }
        "strip-cwd-prefix" => {
            match val.as_str() {
                "auto" => opts.strip_cwd_prefix = StripCwdPrefix::Auto,
                "always" => opts.strip_cwd_prefix = StripCwdPrefix::Always,
                "never" => opts.strip_cwd_prefix = StripCwdPrefix::Never,
                _ => return Some(format!("invalid value '{}' for '--strip-cwd-prefix'", val)),
            }
        }
        "unrestricted" => {
            opts.hidden = true;
            opts.no_ignore = true;
        }
        _ => {}
    }
    None
}

fn parse_file_type(s: &str) -> Option<FileType> {
    match s {
        "f" | "file" => Some(FileType::File),
        "d" | "dir" | "directory" => Some(FileType::Directory),
        "l" | "symlink" => Some(FileType::Symlink),
        "x" | "executable" => Some(FileType::Executable),
        "e" | "empty" => Some(FileType::Empty),
        "s" | "socket" => Some(FileType::Socket),
        "p" | "pipe" => Some(FileType::Pipe),
        "b" | "block-device" => Some(FileType::BlockDevice),
        "c" | "char-device" => Some(FileType::CharDevice),
        _ => None,
    }
}

fn parse_size_filter(s: &str) -> Result<SizeFilter, String> {
    let s = s.trim();
    let (cmp, rest) = if s.starts_with('+') {
        (SizeCmp::Plus, &s[1..])
    } else if s.starts_with('-') {
        (SizeCmp::Minus, &s[1..])
    } else {
        (SizeCmp::Equal, s)
    };

    // Find where digits end
    let num_end = rest.find(|c: char| !c.is_ascii_digit()).unwrap_or(rest.len());
    if num_end == 0 {
        return Err(format!("invalid size filter: {}", s));
    }
    let num: u64 = rest[..num_end].parse().map_err(|_| format!("invalid size: {}", s))?;
    let unit = rest[num_end..].trim().to_lowercase();

    let bytes = match unit.as_str() {
        "b" | "" => num,
        "k" => num * 1000,
        "m" => num * 1_000_000,
        "g" => num * 1_000_000_000,
        "t" => num * 1_000_000_000_000,
        "ki" => num * 1024,
        "mi" => num * 1024 * 1024,
        "gi" => num * 1024 * 1024 * 1024,
        "ti" => num * 1024 * 1024 * 1024 * 1024,
        _ => return Err(format!("unknown size unit: {}", unit)),
    };

    Ok(SizeFilter { cmp, bytes })
}

fn parse_owner_filter(s: &str) -> Result<OwnerFilter, String> {
    let (exclude, s) = if s.starts_with('!') {
        (true, &s[1..])
    } else {
        (false, s)
    };

    if let Some(colon_pos) = s.find(':') {
        let user_str = &s[..colon_pos];
        let group_str = &s[colon_pos+1..];

        let user = if user_str.is_empty() {
            None
        } else {
            Some(parse_owner_spec(user_str)?)
        };

        let group = if group_str.is_empty() {
            None
        } else {
            Some(parse_owner_spec(group_str)?)
        };

        Ok(OwnerFilter { user, group, exclude })
    } else {
        let user = Some(parse_owner_spec(s)?);
        Ok(OwnerFilter { user, group: None, exclude })
    }
}

fn parse_owner_spec(s: &str) -> Result<OwnerSpec, String> {
    if let Ok(id) = s.parse::<u32>() {
        Ok(OwnerSpec { by_name: None, by_id: Some(id) })
    } else {
        Ok(OwnerSpec { by_name: Some(s.to_string()), by_id: None })
    }
}
