// Simple regex engine for fd (using Rust's std library)
// Implements basic regex features needed for fd

/// A compiled pattern for matching
pub struct Pattern {
    regex: SimpleRegex,
    case_insensitive: bool,
}

pub struct SimpleRegex {
    nodes: Vec<Node>,
    anchored_start: bool,
    anchored_end: bool,
}

#[derive(Clone, Debug)]
enum Node {
    Literal(char),
    AnyChar,           // .
    CharClass(Vec<CharRange>, bool), // [chars] or [^chars]
    Star(Box<Node>),   // *
    Plus(Box<Node>),   // +
    Question(Box<Node>), // ?
    Group(Vec<Vec<Node>>), // (a|b|c)
    WordBoundary,      // \b
    NonWordBoundary,   // \B
}

#[derive(Clone, Debug)]
struct CharRange {
    start: char,
    end: char,
}

impl Pattern {
    pub fn new(pattern: &str, case_insensitive: bool) -> Result<Self, String> {
        let regex = SimpleRegex::parse(pattern)?;
        Ok(Pattern { regex, case_insensitive })
    }

    pub fn is_match(&self, text: &str) -> bool {
        let text = if self.case_insensitive {
            text.to_lowercase()
        } else {
            text.to_string()
        };
        self.regex.is_match(&text)
    }
}

impl SimpleRegex {
    fn parse(pattern: &str) -> Result<Self, String> {
        let chars: Vec<char> = pattern.chars().collect();
        let mut pos = 0;

        let anchored_start = if pos < chars.len() && chars[pos] == '^' {
            pos += 1;
            true
        } else {
            false
        };

        let end = chars.len();
        let anchored_end = if end > 0 && chars[end - 1] == '$' && (end < 2 || chars[end - 2] != '\\') {
            true
        } else {
            false
        };

        let pat_end = if anchored_end && !pattern.ends_with("\\$") {
            end - 1
        } else {
            end
        };

        let nodes = parse_nodes(&chars, &mut pos, pat_end, false)?;

        Ok(SimpleRegex {
            nodes,
            anchored_start,
            anchored_end,
        })
    }

    fn is_match(&self, text: &str) -> bool {
        let text_chars: Vec<char> = text.chars().collect();
        let tlen = text_chars.len();

        if self.anchored_start && self.anchored_end {
            return match_nodes(&self.nodes, &text_chars, 0) == Some(tlen);
        } else if self.anchored_start {
            return match_nodes(&self.nodes, &text_chars, 0).is_some();
        } else if self.anchored_end {
            for start in 0..=tlen {
                if let Some(end) = match_nodes(&self.nodes, &text_chars, start) {
                    if end == tlen {
                        return true;
                    }
                }
            }
            return false;
        } else {
            for start in 0..=tlen {
                if match_nodes(&self.nodes, &text_chars, start).is_some() {
                    return true;
                }
            }
            return false;
        }
    }
}

fn parse_nodes(chars: &[char], pos: &mut usize, end: usize, in_group: bool) -> Result<Vec<Node>, String> {
    let mut nodes = Vec::new();
    while *pos < end {
        if in_group && *pos < chars.len() && (chars[*pos] == '|' || chars[*pos] == ')') {
            break;
        }
        let node = parse_atom(chars, pos, end, in_group)?;
        // Check for quantifier
        let node = if *pos < end {
            match chars.get(*pos) {
                Some('*') => {
                    *pos += 1;
                    let greedy = chars.get(*pos) != Some(&'?');
                    if chars.get(*pos) == Some(&'?') { *pos += 1; }
                    Node::Star(Box::new(node))
                }
                Some('+') => {
                    *pos += 1;
                    if chars.get(*pos) == Some(&'?') { *pos += 1; }
                    Node::Plus(Box::new(node))
                }
                Some('?') => {
                    *pos += 1;
                    if chars.get(*pos) == Some(&'?') { *pos += 1; }
                    Node::Question(Box::new(node))
                }
                Some('{') => {
                    // {n}, {n,}, {n,m} - simplified: just treat as literal if can't parse
                    let save = *pos;
                    *pos += 1;
                    let mut num_str = String::new();
                    while *pos < end && chars[*pos].is_ascii_digit() {
                        num_str.push(chars[*pos]);
                        *pos += 1;
                    }
                    if *pos < end && (chars[*pos] == '}' || chars[*pos] == ',') {
                        // skip the quantifier
                        while *pos < end && chars[*pos] != '}' { *pos += 1; }
                        if *pos < end { *pos += 1; }
