// Simple glob pattern matcher for fd

pub struct GlobPattern {
    pattern: String,
    case_insensitive: bool,
}

impl GlobPattern {
    pub fn new(pattern: &str, case_insensitive: bool) -> Self {
        GlobPattern {
            pattern: pattern.to_string(),
            case_insensitive,
        }
    }

    pub fn is_match(&self, text: &str) -> bool {
        let (pat, txt) = if self.case_insensitive {
            (self.pattern.to_lowercase(), text.to_lowercase())
        } else {
            (self.pattern.clone(), text.to_string())
        };
        glob_match(&pat, &txt)
    }

    pub fn is_match_path(&self, text: &str) -> bool {
        let (pat, txt) = if self.case_insensitive {
            (self.pattern.to_lowercase(), text.to_lowercase())
        } else {
            (self.pattern.clone(), text.to_string())
        };
        glob_match_path(&pat, &txt)
    }
}

fn glob_match(pattern: &str, text: &str) -> bool {
    let pat: Vec<char> = pattern.chars().collect();
    let txt: Vec<char> = text.chars().collect();
    glob_match_chars(&pat, &txt, false)
}

fn glob_match_path(pattern: &str, text: &str) -> bool {
    let pat: Vec<char> = pattern.chars().collect();
    let txt: Vec<char> = text.chars().collect();
    glob_match_chars(&pat, &txt, true)
}

fn glob_match_chars(pat: &[char], txt: &[char], path_mode: bool) -> bool {
    match_recursive(pat, txt, 0, 0, path_mode)
}

fn match_recursive(pat: &[char], txt: &[char], pi: usize, ti: usize, path_mode: bool) -> bool {
    if pi == pat.len() && ti == txt.len() {
        return true;
    }
    if pi == pat.len() {
        return false;
    }

    if path_mode && pi + 1 < pat.len() && pat[pi] == '*' && pat[pi + 1] == '*' {
        // ** matches multiple path components
        let mut npi = pi + 2;
        if npi < pat.len() && pat[npi] == '/' {
            npi += 1;
        }
        // Try matching 0 or more path segments
        let mut nti = ti;
        loop {
            if match_recursive(pat, txt, npi, nti, path_mode) {
                return true;
            }
            // Advance to next path component
            while nti < txt.len() && txt[nti] != '/' {
                nti += 1;
            }
