// gitignore/fdignore file support for fd

use std::path::{Path, PathBuf};
use std::fs;
use crate::glob_impl::GlobPattern;

/// A set of ignore rules from a single file
#[derive(Clone)]
pub struct IgnoreRules {
    pub path: PathBuf,  // directory this applies to
    pub rules: Vec<IgnoreRule>,
}

#[derive(Clone)]
pub struct IgnoreRule {
    pub pattern: String,
    pub negation: bool,
    pub dir_only: bool,
    pub anchored: bool,
}

impl IgnoreRules {
    pub fn from_file(ignore_file: &Path) -> Option<Self> {
        let parent = ignore_file.parent()?.to_path_buf();
        let content = fs::read_to_string(ignore_file).ok()?;
        let rules = parse_gitignore(&content);
        Some(IgnoreRules { path: parent, rules })
    }

    /// Check if a path relative to this rule's directory should be ignored
    /// Returns Some(true) if ignored, Some(false) if un-ignored, None if no match
    pub fn is_ignored(&self, rel_path: &str, is_dir: bool) -> Option<bool> {
        let mut result: Option<bool> = None;
        for rule in &self.rules {
            if rule.dir_only && !is_dir {
                continue;
            }
            if matches_ignore_rule(&rule.pattern, rel_path, rule.anchored) {
                result = Some(!rule.negation);
            }
        }
        result
    }
}

fn matches_ignore_rule(pattern: &str, rel_path: &str, anchored: bool) -> bool {
    // Strip trailing /
    let pattern = pattern.trim_end_matches('/');

    if pattern.contains('/') || anchored {
        // Anchored pattern - match against full relative path
        let glob = GlobPattern::new(pattern, false);
        // Try both the full path and just the filename
        if glob.is_match_path(rel_path) {
            return true;
        }
        // Also try matching just the basename component if pattern has no /
        false
    } else {
        // Unanchored - match against each component
        let basename = if let Some(pos) = rel_path.rfind('/') {
            &rel_path[pos+1..]
        } else {
            rel_path
        };
        let glob = GlobPattern::new(pattern, false);
        if glob.is_match(basename) {
            return true;
        }
        // Also try matching path components from the right
        // For example pattern "foo" should match "a/b/foo"
        false
    }
}

fn parse_gitignore(content: &str) -> Vec<IgnoreRule> {
    let mut rules = Vec::new();
    for line in content.lines() {
        let line = line.trim_end_matches('\r');

        // Skip empty lines and comments
        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        // Handle escaped #
        let line = if line.starts_with("\\#") {
            &line[1..]
        } else {
            line
        };

        // Negation
        let (negation, line) = if line.starts_with('!') {
            (true, &line[1..])
        } else {
            (false, line)
        };

        // Skip empty
        if line.is_empty() {
            continue;
        }

        // Dir only?
        let dir_only = line.ends_with('/');
        let line = line.trim_end_matches('/');

        // Anchored?
        let anchored = if line.starts_with('/') {
            true
        } else if line.contains('/') {
            true
        } else {
            false
        };

        let pattern = if line.starts_with('/') {
            line[1..].to_string()
        } else {
            line.to_string()
        };

        rules.push(IgnoreRule {
            pattern,
            negation,
            dir_only,
            anchored,
        });
    }
    rules
}

/// Collection of all ignore rules for a traversal
pub struct IgnoreContext {
    pub rule_sets: Vec<IgnoreRules>,
    pub global_rules: Vec<IgnoreRules>,
    pub extra_files: Vec<IgnoreRules>,
    pub respect_gitignore: bool,
    pub respect_fdignore: bool,
    pub respect_ignore: bool,
    pub in_git_repo: bool,
    pub require_git: bool,
}

impl IgnoreContext {
    pub fn new(
        respect_gitignore: bool,
        respect_fdignore: bool,
        respect_ignore: bool,
        require_git: bool,
        extra_ignore_files: &[PathBuf],
    ) -> Self {
        let global_rules = load_global_ignore_files(respect_gitignore, respect_fdignore);

        let extra_files: Vec<IgnoreRules> = extra_ignore_files.iter()
            .filter_map(|p| IgnoreRules::from_file(p))
            .collect();

        IgnoreContext {
            rule_sets: Vec::new(),
            global_rules,
            extra_files,
            respect_gitignore,
            respect_fdignore,
            respect_ignore,
            in_git_repo: false,
            require_git,
        }
    }

    pub fn check_git_repo(&mut self, path: &Path) {
        // Walk up from path to find .git
        let mut p = path.to_path_buf();
        loop {
            if p.join(".git").exists() {
                self.in_git_repo = true;
                return;
            }
            if !p.pop() {
                break;
            }
        }
        self.in_git_repo = false;
    }

    pub fn load_for_dir(&mut self, dir: &Path) {
        // Load .gitignore, .ignore, .fdignore for this directory
        if self.respect_gitignore && (self.in_git_repo || !self.require_git) {
            let gi = dir.join(".gitignore");
            if gi.exists() {
                if let Some(rules) = IgnoreRules::from_file(&gi) {
                    self.rule_sets.push(rules);
                }
            }
        }
        if self.respect_ignore {
            let ig = dir.join(".ignore");
            if ig.exists() {
                if let Some(rules) = IgnoreRules::from_file(&ig) {
                    self.rule_sets.push(rules);
                }
            }
        }
        if self.respect_fdignore {
            let fdi = dir.join(".fdignore");
            if fdi.exists() {
                if let Some(rules) = IgnoreRules::from_file(&fdi) {
                    self.rule_sets.push(rules);
                }
            }
        }
    }

    /// Check if an absolute path should be ignored
    pub fn is_ignored(&self, abs_path: &Path, is_dir: bool) -> bool {
        // Check all rule sets (most specific last wins)
        let mut result = false;

        // Check global rules
        for rule_set in &self.global_rules {
            if let Some(rel) = get_relative_to(&rule_set.path, abs_path) {
                if let Some(ignored) = rule_set.is_ignored(&rel, is_dir) {
                    result = ignored;
                }
            }
        }

        // Check extra files
        for rule_set in &self.extra_files {
            if let Some(rel) = get_relative_to(&rule_set.path, abs_path) {
                if let Some(ignored) = rule_set.is_ignored(&rel, is_dir) {
                    result = ignored;
                }
