            line[1..].to_string()
        } else {
            line.to_string()
        };

        rules.push(IgnoreRule {
            pattern,
            negation,
            dir_only,
            anchored,
        });
    }
    rules
}

/// Collection of all ignore rules for a traversal
pub struct IgnoreContext {
    pub rule_sets: Vec<IgnoreRules>,
    pub global_rules: Vec<IgnoreRules>,
    pub extra_files: Vec<IgnoreRules>,
    pub respect_gitignore: bool,
    pub respect_fdignore: bool,
    pub respect_ignore: bool,
    pub in_git_repo: bool,
    pub require_git: bool,
}

impl IgnoreContext {
    pub fn new(
        respect_gitignore: bool,
        respect_fdignore: bool,
        respect_ignore: bool,
        require_git: bool,
        extra_ignore_files: &[PathBuf],
    ) -> Self {
        let global_rules = load_global_ignore_files(respect_gitignore, respect_fdignore);

        let extra_files: Vec<IgnoreRules> = extra_ignore_files.iter()
            .filter_map(|p| IgnoreRules::from_file(p))
            .collect();

        IgnoreContext {
            rule_sets: Vec::new(),
            global_rules,
            extra_files,
            respect_gitignore,
            respect_fdignore,
            respect_ignore,
            in_git_repo: false,
            require_git,
        }
    }

    pub fn check_git_repo(&mut self, path: &Path) {
        // Walk up from path to find .git
        let mut p = path.to_path_buf();
        loop {
            if p.join(".git").exists() {
                self.in_git_repo = true;
                return;
            }
            if !p.pop() {
                break;
            }
        }
        self.in_git_repo = false;
    }

    pub fn load_for_dir(&mut self, dir: &Path) {
        // Load .gitignore, .ignore, .fdignore for this directory
        if self.respect_gitignore && (self.in_git_repo || !self.require_git) {
            let gi = dir.join(".gitignore");
            if gi.exists() {
                if let Some(rules) = IgnoreRules::from_file(&gi) {
                    self.rule_sets.push(rules);
                }
            }
        }
        if self.respect_ignore {
            let ig = dir.join(".ignore");
            if ig.exists() {
                if let Some(rules) = IgnoreRules::from_file(&ig) {
                    self.rule_sets.push(rules);
                }
            }
        }
        if self.respect_fdignore {
            let fdi = dir.join(".fdignore");
            if fdi.exists() {
                if let Some(rules) = IgnoreRules::from_file(&fdi) {
                    self.rule_sets.push(rules);
                }
            }
        }
    }

    /// Check if an absolute path should be ignored
    pub fn is_ignored(&self, abs_path: &Path, is_dir: bool) -> bool {
        // Check all rule sets (most specific last wins)
        let mut result = false;

        // Check global rules
        for rule_set in &self.global_rules {
            if let Some(rel) = get_relative_to(&rule_set.path, abs_path) {
                if let Some(ignored) = rule_set.is_ignored(&rel, is_dir) {
                    result = ignored;
                }
            }
        }

        // Check extra files
        for rule_set in &self.extra_files {
            if let Some(rel) = get_relative_to(&rule_set.path, abs_path) {
                if let Some(ignored) = rule_set.is_ignored(&rel, is_dir) {
                    result = ignored;
                }
            }
        }

        // Check local rule sets
        for rule_set in &self.rule_sets {
            if let Some(rel) = get_relative_to(&rule_set.path, abs_path) {
                if let Some(ignored) = rule_set.is_ignored(&rel, is_dir) {
                    result = ignored;
                }
            }
        }

        result
    }
}

fn get_relative_to(base: &Path, path: &Path) -> Option<String> {
    path.strip_prefix(base).ok().map(|p| p.to_string_lossy().into_owned())
}

fn load_global_ignore_files(gitignore: bool, fdignore: bool) -> Vec<IgnoreRules> {
    let mut rules = Vec::new();

    // Global gitignore
    if gitignore {
        // Try XDG_CONFIG_HOME/git/ignore or $HOME/.config/git/ignore
        let global_gitignore = get_global_gitignore_path();
        if let Some(path) = global_gitignore {
            if let Some(r) = IgnoreRules::from_file(&path) {
                rules.push(r);
            }
        }
    }

    // Global fd ignore
    if fdignore {
        let global_fd_ignore = get_global_fd_ignore_path();
        if let Some(path) = global_fd_ignore {
            if let Some(r) = IgnoreRules::from_file(&path) {
                rules.push(r);
            }
        }
    }

    rules
}

fn get_global_gitignore_path() -> Option<PathBuf> {
    // Check git config for core.excludesFile
    if let Ok(output) = std::process::Command::new("git")
        .args(["config", "--global", "core.excludesFile"])
        .output()
    {
        let path_str = String::from_utf8_lossy(&output.stdout).trim().to_string();
        if !path_str.is_empty() {
            return Some(PathBuf::from(path_str));
        }
    }

    // Default location
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        let p = PathBuf::from(xdg).join("git").join("ignore");
        if p.exists() { return Some(p); }
    }
    if let Ok(home) = std::env::var("HOME") {
        let p = PathBuf::from(home).join(".config").join("git").join("ignore");
        if p.exists() { return Some(p); }
    }
    None
}

fn get_global_fd_ignore_path() -> Option<PathBuf> {
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        let p = PathBuf::from(xdg).join("fd").join("ignore");
        if p.exists() { return Some(p); }
    }
    if let Ok(home) = std::env::var("HOME") {
        let p = PathBuf::from(home).join(".config").join("fd").join("ignore");
        if p.exists() { return Some(p); }
    }
    None
}
