                        // fd colors: \033[38;5;81mc\033[0m\033[38;5;81m/\033[0m
                        // The name part (c) is colored, and / is colored
                        // prefix (a/b/) is not colored
                        if !prefix.is_empty() {
                            let name = &display[last_slash+1..].trim_end_matches('/');
                            let suffix = if display.ends_with('/') { "/" } else { "" };
                            return format!("{}\x1b[{}m{}\x1b[0m\x1b[{}m{}\x1b[0m",
                                prefix_uncolored(prefix),
                                dir_code, name, dir_code, suffix);
                        }
                    }
                    // Top-level directory like "subdir/"
                    let name = display.trim_end_matches('/');
                    let suffix = if display.ends_with('/') { "/" } else { "" };
                    return format!("\x1b[{}m{}\x1b[0m\x1b[{}m{}\x1b[0m",
                        code, name, code, suffix);
                }
            }
            format!("\x1b[{}m{}\x1b[0m", code, display)
        } else {
            display.to_string()
        }
    }

    fn get_color(&self, path: &Path) -> Option<String> {
        // Try to get metadata
        let meta = path.symlink_metadata().ok();

        if let Some(ref m) = meta {
            let ft = m.file_type();

            if ft.is_symlink() {
                return self.link_color.clone();
            }

            if ft.is_dir() {
                return self.dir_color.clone();
            }

            if is_socket_type(&ft) {
                return self.socket_color.clone();
            }
            if is_fifo_type(&ft) {
                return self.fifo_color.clone();
            }
            if is_block_device(&ft) {
                return self.block_color.clone();
            }
            if is_char_device(&ft) {
                return self.char_color.clone();
            }

            if ft.is_file() {
                // Check extension first
                if let Some(ext) = path.extension() {
                    let ext_lower = ext.to_string_lossy().to_lowercase();
                    if let Some(color) = self.ext_colors.get(&ext_lower) {
                        return Some(color.clone());
                    }
                }

                // Check if executable
                let perms = m.permissions().mode();
                if perms & 0o111 != 0 {
                    return self.exec_color.clone();
                }
            }
        }

        None
    }
}

fn prefix_uncolored(s: &str) -> &str {
    s
}

fn ls_to_ansi(code: &str) -> String {
    // LS_COLORS codes are already in ANSI format (e.g., "01;34")
    code.to_string()
}

