fn is_socket_type(ft: &std::fs::FileType) -> bool {
    ft.is_socket()
}

fn is_fifo_type(ft: &std::fs::FileType) -> bool {
    ft.is_fifo()
}

fn is_block_device(ft: &std::fs::FileType) -> bool {
    ft.is_block_device()
}

fn is_char_device(ft: &std::fs::FileType) -> bool {
    ft.is_char_device()
}
