// exec and exec-batch command execution for fd

use std::path::{Path, PathBuf};
use std::process::Command;

use crate::args::{Options, ExecCommand, StripCwdPrefix};

pub fn run_exec(results: &[PathBuf], opts: &Options) {
    for cmd in &opts.exec_cmds {
        for path in results {
            let path_str = format_path(path, opts, true);
            let cmd_args = substitute_placeholders(&cmd.args, &path_str, path);

            if !cmd_args.is_empty() {
                let mut child = Command::new(&cmd_args[0]);
                child.args(&cmd_args[1..]);

                if opts.print0 {
                    // Run command and separate output with null char
                    // For simplicity, just run it
                }

                let _ = child.status();
            }
        }
    }
}

pub fn run_exec_batch(results: &[PathBuf], opts: &Options) {
    for cmd in &opts.exec_batch_cmds {
        if cmd.args.is_empty() { continue; }

        let batch_size = if opts.batch_size == 0 { results.len() } else { opts.batch_size };

        let all_paths: Vec<String> = results.iter()
            .map(|p| format_path(p, opts, false))
            .collect();

        for chunk in all_paths.chunks(if batch_size == 0 { all_paths.len().max(1) } else { batch_size }) {
            let mut final_args: Vec<String> = Vec::new();

            // Check if any placeholder in the command
            let has_placeholder = cmd.args.iter().any(|a| contains_placeholder(a));

            if has_placeholder {
                // Expand each path for each placeholder arg
                let prefix_args: Vec<String> = cmd.args[..1].to_vec(); // command name
                let template_args = &cmd.args[1..];

                let mut args = Vec::new();
                args.push(cmd.args[0].clone());

                for tmpl in template_args {
                    if contains_placeholder(tmpl) {
                        for path_str in chunk {
                            let p = PathBuf::from(path_str);
                            let expanded = substitute_single_placeholder(tmpl, path_str, &p);
                            args.push(expanded);
                        }
                    } else {
                        args.push(tmpl.clone());
                    }
                }

                if !args.is_empty() {
                    let _ = Command::new(&args[0]).args(&args[1..]).status();
                }
            } else {
                // No placeholder - append all paths
                let mut args = cmd.args.clone();
                args.extend(chunk.iter().cloned());
                if !args.is_empty() {
                    let _ = Command::new(&args[0]).args(&args[1..]).status();
                }
            }
        }
