        .map(|p| GlobPattern::new(p, false))
        .collect();

    let respect_gitignore = !opts.no_ignore && !opts.no_ignore_vcs;
    let respect_fdignore = !opts.no_ignore;
    let respect_ignore = !opts.no_ignore;
    let require_git = !opts.no_require_git;

