        let abs_search = if is_abs {
            search_path.clone()
        } else {
            cwd.join(search_path)
        };

        let abs_search = match fs::canonicalize(&abs_search) {
            Ok(p) => p,
            Err(_) => abs_search,
        };

        let mut ignore_ctx = IgnoreContext::new(
            respect_gitignore,
            respect_fdignore,
            respect_ignore,
            require_git,
            &opts.ignore_files,
        );

        if require_git {
            ignore_ctx.check_git_repo(&abs_search);
        } else {
            ignore_ctx.in_git_repo = true;
        }

        ignore_ctx.load_for_dir(&abs_search);

        // For display: if is_abs, show full absolute paths
        // If relative, show paths relative to the search_path prefix
        let display_root = if is_abs {
            // We'll show absolute paths from cwd context
            // Actually show relative to cwd if possible, or absolute
            // The original fd shows absolute when given absolute search path
            abs_search.clone()
        } else {
            // Search path is like "." or "somedir" - show relative paths
            // The display base is the parent of search_path
            abs_search.clone()
        };

        walk_dir(
            &abs_search,
            &abs_search,
            &display_root,
            0,
            opts,
            &matcher,
            &exclude_globs,
            &changed_within,
            &changed_before,
            &opts.size_filters,
            &opts.owner_filter,
            &mut ignore_ctx,
            &cwd,
            is_abs,
            &search_path,
            &mut results,
            &count,
            max_results,
        );
    }

    results.sort();
    results
}

fn walk_dir(
    path: &Path,        // actual path to walk
    root: &Path,        // root of this search (absolute)
    display_root: &Path, // for computing display paths
    depth: usize,
    opts: &Options,
    matcher: &Matcher,
    exclude_globs: &[GlobPattern],
    changed_within: &Option<SystemTime>,
    changed_before: &Option<SystemTime>,
    size_filters: &[SizeFilter],
    owner_filter: &Option<OwnerFilter>,
    ignore_ctx: &mut IgnoreContext,
    cwd: &Path,
    search_is_abs: bool,
    search_path_orig: &Path,  // original search path (for display)
    results: &mut Vec<PathBuf>,
    count: &Arc<AtomicUsize>,
    max_results: Option<usize>,
) {
    if let Some(max) = max_results {
        if count.load(Ordering::Relaxed) >= max {
            return;
        }
    }

    if let Some(max_depth) = opts.max_depth {
        if depth >= max_depth {
            return;
        }
    }

    let read_dir = match fs::read_dir(path) {
        Ok(rd) => rd,
        Err(e) => {
            if opts.show_errors {
                eprintln!("[fd error]: {}: {}", path.display(), e);
            }
            return;
        }
    };

    let mut entries: Vec<_> = read_dir.filter_map(|e| e.ok()).collect();
    entries.sort_by(|a, b| a.file_name().cmp(&b.file_name()));

    if depth > 0 {
        ignore_ctx.load_for_dir(path);
    }

    // Check ignore-contain
    for ignore_name in &opts.ignore_contain {
        if path.join(ignore_name).exists() {
            return;
        }
    }

    let start_device = if opts.one_file_system {
        get_device_id(path)
    } else {
        None
    };

    for entry in entries {
        if let Some(max) = max_results {
            if count.load(Ordering::Relaxed) >= max {
                return;
            }
        }

        let entry_path = entry.path(); // absolute path
        let file_name = entry.file_name();
        let name_str = file_name.to_string_lossy();

        // Hidden file check
        if !opts.hidden && name_str.starts_with('.') {
            continue;
        }

        let meta = match entry.metadata() {
            Ok(m) => m,
            Err(e) => {
                if opts.show_errors {
                    eprintln!("[fd error]: {}: {}", entry_path.display(), e);
                }
                continue;
            }
        };

        let is_dir = meta.file_type().is_dir();
        let is_symlink = meta.file_type().is_symlink();

        // Ignore check
        if !opts.no_ignore {
            let ignored = ignore_ctx.is_ignored(&entry_path, is_dir);
            if ignored {
                continue;
            }
        }

        // Exclude patterns
        let should_exclude = exclude_globs.iter().any(|g| {
            g.is_match(&name_str) || 
            // Also match against relative path from root
            if let Ok(rel) = entry_path.strip_prefix(root) {
                g.is_match_path(&rel.to_string_lossy())
            } else {
                false
            }
        });
        if should_exclude {
            continue;
        }

        let current_depth = depth + 1;
        let should_check = opts.min_depth.map(|min| current_depth >= min).unwrap_or(true);

        if should_check {
            let matched = check_entry(
                &entry_path,
                &name_str,
                &meta,
                current_depth,
                opts,
                matcher,
                changed_within,
                changed_before,
                size_filters,
                owner_filter,
                is_symlink,
                root,
                cwd,
                search_is_abs,
                search_path_orig,
            );

            if matched {
                if let Some(max) = max_results {
                    if count.load(Ordering::Relaxed) >= max {
                        return;
                    }
                }

                let display = compute_display_path(
                    &entry_path, root, cwd, opts, is_dir || is_symlink && opts.follow_links && {
                        meta.file_type().is_dir()
                    },
                    search_is_abs, search_path_orig
                );
                results.push(display);
                count.fetch_add(1, Ordering::Relaxed);

                if opts.prune && (is_dir || (is_symlink && opts.follow_links)) {
                    continue;
                }
            }
        }

        // Recurse
        if is_dir && !is_symlink {
            if let Some(max_depth) = opts.max_depth {
                if current_depth >= max_depth {
                    continue;
                }
            }

            if opts.one_file_system {
                if let (Some(root_dev), Some(entry_dev)) = (start_device, get_device_id(&entry_path)) {
                    if root_dev != entry_dev {
                        continue;
                    }
                }
            }

            walk_dir(
                &entry_path,
                root,
                display_root,
                current_depth,
                opts,
                matcher,
                exclude_globs,
                changed_within,
                changed_before,
                size_filters,
                owner_filter,
                ignore_ctx,
                cwd,
                search_is_abs,
                search_path_orig,
                results,
                count,
                max_results,
            );
        } else if is_symlink && opts.follow_links {
            let real_meta = match fs::metadata(&entry_path) {
                Ok(m) => m,
                Err(_) => continue,
            };
            if real_meta.is_dir() {
                if let Some(max_depth) = opts.max_depth {
                    if current_depth >= max_depth {
                        continue;
                    }
                }

                if opts.one_file_system {
                    if let (Some(root_dev), Some(entry_dev)) = (start_device, get_device_id(&entry_path)) {
                        if root_dev != entry_dev {
                            continue;
                        }
                    }
                }

                walk_dir(
                    &entry_path,
                    root,
                    display_root,
                    current_depth,
                    opts,
                    matcher,
                    exclude_globs,
                    changed_within,
                    changed_before,
                    size_filters,
                    owner_filter,
                    ignore_ctx,
                    cwd,
                    search_is_abs,
                    search_path_orig,
                    results,
                    count,
                    max_results,
                );
            }
        }
    }
}

fn get_device_id(path: &Path) -> Option<u64> {
    fs::metadata(path).ok().map(|m| m.dev())
}

fn compute_display_path(
    entry_path: &Path,   // absolute
    root: &Path,         // absolute search root
    cwd: &Path,
    opts: &Options,
    is_dir: bool,
    search_is_abs: bool,
    search_path_orig: &Path,
) -> PathBuf {
    let separator = opts.path_separator.as_deref().unwrap_or("/");

    if opts.absolute_path {
        let mut p = entry_path.to_path_buf();
        if is_dir {
            let s = format!("{}{}", p.display(), separator);
            return PathBuf::from(s);
        }
        return p;
    }

    // Compute relative path from root
    let rel = entry_path.strip_prefix(root)
        .map(|r| r.to_path_buf())
        .unwrap_or_else(|_| entry_path.to_path_buf());

    // Build display path
    let display = if search_is_abs {
        // Show full absolute path
        let mut p = root.join(&rel);
        if is_dir {
            let s = format!("{}{}", p.display(), separator);
            return PathBuf::from(s);
        }
        return p;
    } else {
        // Relative: show as "search_path_orig/rel" or just "rel" if search_path is "."
        let orig = search_path_orig.to_string_lossy();
        let rel_str = rel.to_string_lossy();

        if orig == "." {
            rel_str.into_owned()
        } else {
            format!("{}/{}", orig.trim_end_matches('/'), rel_str)
        }
    };

    if is_dir {
        PathBuf::from(format!("{}{}", display, separator))
    } else {
        PathBuf::from(display)
    }
}

fn check_entry(
    entry_path: &Path,
    name_str: &str,
    meta: &Metadata,
    depth: usize,
    opts: &Options,
    matcher: &Matcher,
    changed_within: &Option<SystemTime>,
    changed_before: &Option<SystemTime>,
    size_filters: &[SizeFilter],
    owner_filter: &Option<OwnerFilter>,
    is_symlink: bool,
    root: &Path,
    cwd: &Path,
    search_is_abs: bool,
    search_path_orig: &Path,
) -> bool {
    let ft = meta.file_type();
    let is_dir = ft.is_dir();
    let is_file = ft.is_file();
    let is_socket = ft.is_socket();
    let is_fifo = ft.is_fifo();
    let is_block = ft.is_block_device();
    let is_char = ft.is_char_device();

    // Type filter
    if !opts.file_types.is_empty() {
        let has_exec = opts.file_types.contains(&FileType::Executable);
        let has_empty = opts.file_types.contains(&FileType::Empty);
        let has_file_t = opts.file_types.contains(&FileType::File);
        let has_dir_t = opts.file_types.contains(&FileType::Directory);

        if has_exec {
            // executable implies file
            if !is_file { return false; }
            if meta.permissions().mode() & 0o111 == 0 { return false; }
        } else if has_empty {
            if has_file_t && !has_dir_t {
                if !is_file || meta.len() != 0 { return false; }
            } else if !has_file_t && has_dir_t {
                if !is_dir || !is_empty_dir(entry_path) { return false; }
            } else if !has_file_t && !has_dir_t {
                let is_empty_entry = (is_file && meta.len() == 0) ||
                               (is_dir && is_empty_dir(entry_path));
                if !is_empty_entry { return false; }
            } else {
                // both file and dir with empty
                let is_empty_entry = (is_file && meta.len() == 0) ||
                               (is_dir && is_empty_dir(entry_path));
                if !is_empty_entry { return false; }
            }
        } else {
            let type_match = opts.file_types.iter().any(|ft_filter| {
                match ft_filter {
                    FileType::File => is_file,
                    FileType::Directory => is_dir,
                    FileType::Symlink => is_symlink,
                    FileType::Executable => is_file && meta.permissions().mode() & 0o111 != 0,
                    FileType::Empty => (is_file && meta.len() == 0) || (is_dir && is_empty_dir(entry_path)),
                    FileType::Socket => is_socket,
                    FileType::Pipe => is_fifo,
                    FileType::BlockDevice => is_block,
                    FileType::CharDevice => is_char,
                }
            });
            if !type_match { return false; }
        }
    }

    // Extension filter
    if !opts.extensions.is_empty() {
        let file_ext = Path::new(name_str)
            .extension()
            .map(|e| e.to_string_lossy().to_lowercase())
            .unwrap_or_default();
        if !opts.extensions.iter().any(|e| e == &file_ext) {
            return false;
        }
    }

    // Pattern match
    let match_target = if opts.full_path {
        // Use absolute path for matching
        let abs = entry_path.to_string_lossy().into_owned();
        abs
    } else {
        name_str.to_string()
    };

    if !matcher.matches(&match_target) {
        return false;
    }

    // Size filter
    if !size_filters.is_empty() {
        if !is_file { return false; }
        let file_size = meta.len();
        for sf in size_filters {
            let ok = match sf.cmp {
                SizeCmp::Plus => file_size >= sf.bytes,
                SizeCmp::Minus => file_size <= sf.bytes,
                SizeCmp::Equal => file_size == sf.bytes,
            };
            if !ok { return false; }
        }
    }

    // Time filters
    if let Some(ref newer_than) = changed_within {
        if let Ok(mtime) = meta.modified() {
            if mtime <= *newer_than {
                return false;
            }
        }
    }
    if let Some(ref older_than) = changed_before {
        if let Ok(mtime) = meta.modified() {
            if mtime >= *older_than {
                return false;
            }
        }
    }

    // Owner filter
    if let Some(ref of) = owner_filter {
        let uid = meta.uid();
        let gid = meta.gid();
        let user_match = of.user.as_ref().map(|s| check_owner_spec(s, uid, true)).unwrap_or(true);
        let group_match = of.group.as_ref().map(|s| check_owner_spec(s, gid, false)).unwrap_or(true);
        let matched = user_match && group_match;
        if of.exclude {
            if matched { return false; }
        } else {
            if !matched { return false; }
        }
    }

    true
}

fn check_owner_spec(spec: &OwnerSpec, id: u32, is_user: bool) -> bool {
    if let Some(ref_id) = spec.by_id {
        return id == ref_id;
    }
    if let Some(ref name) = spec.by_name {
        if is_user {
            return lookup_uid(name).map(|uid| uid == id).unwrap_or(false);
        } else {
            return lookup_gid(name).map(|gid| gid == id).unwrap_or(false);
        }
    }
    true
}

fn lookup_uid(name: &str) -> Option<u32> {
    if let Ok(content) = std::fs::read_to_string("/etc/passwd") {
        for line in content.lines() {
            let parts: Vec<&str> = line.split(':').collect();
            if parts.len() >= 3 && parts[0] == name {
                return parts[2].parse().ok();
            }
        }
    }
    None
}

fn lookup_gid(name: &str) -> Option<u32> {
    if let Ok(content) = std::fs::read_to_string("/etc/group") {
        for line in content.lines() {
            let parts: Vec<&str> = line.split(':').collect();
            if parts.len() >= 3 && parts[0] == name {
                return parts[2].parse().ok();
            }
        }
    }
    None
}

fn is_empty_dir(path: &Path) -> bool {
    fs::read_dir(path)
        .map(|mut d| d.next().is_none())
        .unwrap_or(false)
}

pub enum Matcher {
    Empty,
    Regex(Pattern, Vec<Pattern>),
    Glob(GlobPattern, Vec<GlobPattern>),
    Fixed(String, bool, Vec<String>),
}

impl Matcher {
    pub fn matches(&self, text: &str) -> bool {
        match self {
            Matcher::Empty => true,
            Matcher::Regex(main, ands) => {
                main.is_match(text) && ands.iter().all(|p| p.is_match(text))
            }
            Matcher::Glob(main, ands) => {
                main.is_match(text) && ands.iter().all(|p| p.is_match(text))
            }
            Matcher::Fixed(pat, ci, ands) => {
                let (haystack, needle) = if *ci {
                    (text.to_lowercase(), pat.to_lowercase())
                } else {
                    (text.to_string(), pat.clone())
                };
                haystack.contains(&needle) &&
                ands.iter().all(|p| {
                    let p_low = if *ci { p.to_lowercase() } else { p.clone() };
                    haystack.contains(&p_low)
                })
            }
        }
    }
}

pub fn build_matcher(opts: &Options) -> Result<Matcher, String> {
    let pattern = match &opts.pattern {
        None => return Ok(Matcher::Empty),
        Some(p) if p.is_empty() => return Ok(Matcher::Empty),
        Some(p) => p.as_str(),
    };

    let case_insensitive = if opts.case_sensitive {
        false
    } else if opts.ignore_case {
        true
    } else {
        !pattern.chars().any(|c| c.is_uppercase())
    };

    if opts.fixed_strings {
        let and_pats: Vec<String> = opts.and_patterns.clone();
        return Ok(Matcher::Fixed(
            pattern.to_string(),
            case_insensitive,
            and_pats,
        ));
    }

    if opts.glob {
        let main = GlobPattern::new(pattern, case_insensitive);
        let ands: Vec<GlobPattern> = opts.and_patterns.iter()
            .map(|p| GlobPattern::new(p, case_insensitive))
            .collect();
        return Ok(Matcher::Glob(main, ands));
    }

    // Regex mode
    let main = Pattern::new(pattern, case_insensitive)
        .map_err(|e| format!("invalid regex pattern '{}': {}", pattern, e))?;
    let ands: Vec<Pattern> = opts.and_patterns.iter()
        .map(|p| Pattern::new(p, case_insensitive))
        .collect::<Result<Vec<_>, _>>()
        .map_err(|e| format!("invalid and pattern: {}", e))?;
    Ok(Matcher::Regex(main, ands))
}

fn parse_time_filter(s: &str) -> Option<SystemTime> {
    let s = s.trim();

    if s.starts_with('@') {
        let ts: i64 = s[1..].parse().ok()?;
        let dur = if ts >= 0 {
            UNIX_EPOCH + std::time::Duration::from_secs(ts as u64)
        } else {
            UNIX_EPOCH - std::time::Duration::from_secs((-ts) as u64)
        };
        return Some(dur);
    }

    if let Some(dur) = parse_duration(s) {
        return Some(SystemTime::now() - dur);
    }

    if let Some(ts) = parse_datetime(s) {
        return Some(ts);
    }

    None
}

fn parse_duration(s: &str) -> Option<std::time::Duration> {
    let num_end = s.find(|c: char| !c.is_ascii_digit()).unwrap_or(s.len());
    if num_end == 0 { return None; }

    let num: u64 = s[..num_end].parse().ok()?;
    let unit = s[num_end..].trim().to_lowercase();

    let secs = match unit.as_str() {
        "s" | "sec" | "secs" | "second" | "seconds" => num,
        "m" | "min" | "mins" | "minute" | "minutes" => num * 60,
        "h" | "hr" | "hrs" | "hour" | "hours" => num * 3600,
        "d" | "day" | "days" => num * 86400,
        "w" | "week" | "weeks" => num * 7 * 86400,
        "month" | "months" => num * 30 * 86400,
        "year" | "years" => num * 365 * 86400,
        _ => return None,
    };

    Some(std::time::Duration::from_secs(secs))
}

fn parse_datetime(s: &str) -> Option<SystemTime> {
    let parts: Vec<&str> = s.splitn(2, ' ').collect();
    let date_parts: Vec<&str> = parts[0].split('-').collect();
    if date_parts.len() != 3 { return None; }

    let year: i32 = date_parts[0].parse().ok()?;
    let month: u32 = date_parts[1].parse().ok()?;
    let day: u32 = date_parts[2].parse().ok()?;

    let (hour, min, sec) = if parts.len() > 1 {
        let time_parts: Vec<&str> = parts[1].split(':').collect();
        if time_parts.len() < 2 { return None; }
        let h: u32 = time_parts[0].parse().ok()?;
        let m: u32 = time_parts[1].parse().ok()?;
        let s: u32 = time_parts.get(2).and_then(|s| s.parse().ok()).unwrap_or(0);
        (h, m, s)
    } else {
        (0, 0, 0)
    };

    let days_since_epoch = days_from_civil(year, month, day)?;
    let total_secs = days_since_epoch as u64 * 86400 +
                     hour as u64 * 3600 +
                     min as u64 * 60 +
                     sec as u64;

    Some(UNIX_EPOCH + std::time::Duration::from_secs(total_secs))
}

fn days_from_civil(y: i32, m: u32, d: u32) -> Option<i64> {
    let y = y as i64;
    let m = m as i64;
    let d = d as i64;

    let y = if m <= 2 { y - 1 } else { y };
    let era = (if y >= 0 { y } else { y - 399 }) / 400;
    let yoe = y - era * 400;
    let doy = (153 * (m + (if m > 2 { -3 } else { 9 })) + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    let days = era * 146097 + doe - 719468;
    Some(days)
}
