            if entry.is_empty() { continue; }
            if let Some(eq_pos) = entry.find('=') {
                let key = &entry[..eq_pos];
                let val = entry[eq_pos+1..].to_string();
                match key {
                    "di" => colors.dir_color = if val == "0" || val.is_empty() { None } else { Some(val) },
                    "ln" => colors.link_color = if val == "0" || val.is_empty() { None } else { Some(val) },
                    "ex" => colors.exec_color = if val == "0" || val.is_empty() { None } else { Some(val) },
                    "pi" => colors.fifo_color = if val == "0" || val.is_empty() { None } else { Some(val) },
                    "so" => colors.socket_color = if val == "0" || val.is_empty() { None } else { Some(val) },
                    "bd" => colors.block_color = if val == "0" || val.is_empty() { None } else { Some(val) },
                    "cd" => colors.char_color = if val == "0" || val.is_empty() { None } else { Some(val) },
                    _ => {
                        if let Some(ext) = key.strip_prefix("*.") {
                            if val == "0" || val.is_empty() {
                                colors.ext_colors.remove(&ext.to_lowercase());
                            } else {
                                colors.ext_colors.insert(ext.to_lowercase(), val);
                            }
                        }
                    }
                }
            }
        }

        colors
