    pub fn colorize(&self, path: &Path, display: &str) -> String {
        // Get the actual file metadata (symlink_metadata to detect symlinks)
        let meta = path.symlink_metadata().ok();

        if let Some(ref m) = meta {
            let ft = m.file_type();

            // Check special types first
            if ft.is_symlink() {
                return apply_color(display, &self.link_color, &self.reset);
