// exec and exec-batch command execution for fd

use std::path::{Path, PathBuf};
use std::process::Command;

use crate::args::{Options, ExecCommand, StripCwdPrefix};

pub fn run_exec(results: &[PathBuf], opts: &Options) {
    for cmd in &opts.exec_cmds {
        for path in results {
            let path_str = format_path_for_exec(path, opts);
            let cmd_args = substitute_placeholders(&cmd.args, &path_str, path);

            if !cmd_args.is_empty() {
                let _ = Command::new(&cmd_args[0])
                    .args(&cmd_args[1..])
                    .status();
            }
        }
    }
}

pub fn run_exec_batch(results: &[PathBuf], opts: &Options) {
    for cmd in &opts.exec_batch_cmds {
        if cmd.args.is_empty() { continue; }

        // batch_size=0 means no limit (but system limits may apply)
        let batch_size = if opts.batch_size == 0 { results.len().max(1) } else { opts.batch_size };

        let all_paths: Vec<String> = results.iter()
            .map(|p| format_path_for_exec(p, opts))
            .collect();

        for chunk in all_paths.chunks(batch_size) {
            let has_placeholder = cmd.args.iter().any(|a| contains_placeholder(a));

            if has_placeholder {
                let mut args = vec![cmd.args[0].clone()];
                for tmpl in &cmd.args[1..] {
                    if contains_placeholder(tmpl) {
                        for path_str in chunk {
                            let p = PathBuf::from(path_str);
                            let expanded = substitute_single_placeholder(tmpl, path_str, &p);
                            args.push(expanded);
                        }
                    } else {
                        args.push(tmpl.clone());
                    }
                }
                if !args.is_empty() {
                    let _ = Command::new(&args[0]).args(&args[1..]).status();
                }
            } else {
                // No placeholder - append all paths at the end
                let mut args = cmd.args.clone();
                args.extend(chunk.iter().cloned());
                if !args.is_empty() {
                    let _ = Command::new(&args[0]).args(&args[1..]).status();
                }
            }
        }
    }
}

/// Format a path for use in exec/exec-batch/print0
/// Adds ./ prefix for relative paths when appropriate
pub fn format_path_for_exec(path: &Path, opts: &Options) -> String {
    let s = path.to_string_lossy().into_owned();

    // Determine if we should strip the ./ prefix
    let should_strip = match opts.strip_cwd_prefix {
        StripCwdPrefix::Always => true,
        StripCwdPrefix::Never => false,
        StripCwdPrefix::Auto => false, // don't strip by default
    };

    if should_strip {
        if let Some(stripped) = s.strip_prefix("./") {
            return stripped.to_string();
        }
        return s;
    }

    // Add ./ prefix for relative paths that don't already have it
    // This is the default behavior for exec, exec-batch, and print0
    if !s.starts_with('/') && !s.starts_with("./") && !s.starts_with("../") {
        format!("./{}", s)
    } else {
        s
    }
}

fn contains_placeholder(s: &str) -> bool {
    // Check for placeholder patterns
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '{' && i + 1 < chars.len() {
            if chars[i + 1] == '{' {
                i += 2; // escaped {
                continue;
            }
            // Find closing }
            let mut j = i + 1;
            while j < chars.len() && chars[j] != '}' {
                j += 1;
            }
            if j < chars.len() {
                let placeholder: String = chars[i+1..j].iter().collect();
                match placeholder.as_str() {
                    "" | "/" | "//" | "." | "/." => return true,
                    _ => {}
                }
            }
        } else if chars[i] == '}' && i + 1 < chars.len() && chars[i + 1] == '}' {
            i += 2;
            continue;
        }
        i += 1;
    }
    false
}

fn substitute_placeholders(tmpl_args: &[String], path_str: &str, path: &Path) -> Vec<String> {
    let has_placeholder = tmpl_args.iter().any(|a| contains_placeholder(a));

    if has_placeholder {
        tmpl_args.iter()
            .map(|a| substitute_single_placeholder(a, path_str, path))
            .collect()
    } else {
        // Implicit {} at end
        let mut args = tmpl_args.to_vec();
        args.push(path_str.to_string());
        args
    }
}

pub fn substitute_single_placeholder(tmpl: &str, path_str: &str, path: &Path) -> String {
    let basename = path.file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| path_str.to_string());

    let parent = path.parent()
        .map(|p| {
            let s = p.to_string_lossy();
            if s.is_empty() { ".".to_string() } else { s.into_owned() }
        })
        .unwrap_or_else(|| ".".to_string());

    let path_no_ext = remove_extension_from_path(path_str, &basename);
    let basename_no_ext = remove_extension_from_basename(&basename);

    // Process the template
    let chars: Vec<char> = tmpl.chars().collect();
    let mut result = String::new();
    let mut i = 0;

    while i < chars.len() {
        if chars[i] == '{' {
            if i + 1 < chars.len() && chars[i + 1] == '{' {
                result.push('{');
                i += 2;
                continue;
            }
            // Find closing }
            let mut j = i + 1;
            while j < chars.len() && chars[j] != '}' {
                j += 1;
            }
            if j < chars.len() {
                let placeholder: String = chars[i+1..j].iter().collect();
                match placeholder.as_str() {
                    "" => result.push_str(path_str),
                    "/" => result.push_str(&basename),
                    "//" => result.push_str(&parent),
                    "." => result.push_str(&path_no_ext),
                    "/." => result.push_str(&basename_no_ext),
                    _ => {
                        result.push('{');
                        result.push_str(&placeholder);
                        result.push('}');
                    }
                }
