            println!("fd {}", VERSION);
            process::exit(0);
        }
    }
}

const VERSION: &str = "10.3.0";

fn run_search(opts: Options) -> i32 {
    let results = walk::collect_results(&opts);

    if opts.quiet {
        return if results.is_empty() { 1 } else { 0 };
    }

    if opts.list_details {
        // Use ls -ld with all results
        let paths: Vec<String> = results.iter()
            .map(|p| p.to_string_lossy().into_owned())
            .collect();
        if !paths.is_empty() {
            let _ = Command::new("ls")
                .args(&["-ld", "--color=auto"])
                .args(&paths)
                .status();
        }
        return 0;
    }

    if !opts.exec_cmds.is_empty() {
        exec::run_exec(&results, &opts);
        return 0;
    }

    if !opts.exec_batch_cmds.is_empty() {
        exec::run_exec_batch(&results, &opts);
        return 0;
    }

    // Regular output
    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());

    let use_color = match opts.color {
        ColorMode::Always => true,
        ColorMode::Never => false,
        ColorMode::Auto => is_tty(),
    };

    // Check NO_COLOR
    let use_color = use_color && std::env::var("NO_COLOR").is_err();

    let ls_colors = if use_color {
        ls_colors::LsColors::from_env()
    } else {
        ls_colors::LsColors::empty()
    };

    // Determine if we should add ./ prefix (for print0 mode)
    let should_add_prefix = match opts.strip_cwd_prefix {
        StripCwdPrefix::Always => false,
        StripCwdPrefix::Never => true,
        StripCwdPrefix::Auto => opts.print0, // add ./ for print0
    };

    for path in &results {
        let display_str = if let Some(ref fmt) = opts.format {
            let path_for_exec = format_path_for_exec(path, &opts);
            apply_format(fmt, path, &path_for_exec)
        } else if opts.print0 {
            // For print0, use the exec format (with ./ prefix)
            format_path_for_exec(path, &opts)
        } else {
            path.to_string_lossy().into_owned()
        };

        if use_color && opts.format.is_none() && !opts.print0 {
            let colored = ls_colors.colorize(path, &display_str);
            if opts.print0 {
                write!(out, "{}\0", colored).ok();
            } else {
                writeln!(out, "{}", colored).ok();
            }
        } else if use_color && opts.format.is_some() {
            // For format, we display the formatted string with the path's color
            let colored = ls_colors.colorize(path, &display_str);
            if opts.print0 {
                write!(out, "{}\0", colored).ok();
            } else {
                writeln!(out, "{}", colored).ok();
            }
        } else {
            if opts.print0 {
                write!(out, "{}\0", display_str).ok();
            } else {
                writeln!(out, "{}", display_str).ok();
            }
        }
    }

    0
}

fn apply_format(fmt: &str, path: &Path, path_str: &str) -> String {
    let basename = path.file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| path_str.to_string());

    let parent = path.parent()
        .map(|p| {
            let s = p.to_string_lossy();
            if s.is_empty() { ".".to_string() } else { s.into_owned() }
        })
        .unwrap_or_else(|| ".".to_string());

    substitute_single_placeholder(fmt, path_str, path)
}

fn is_tty() -> bool {
    unsafe { isatty(1) != 0 }
}

