            if !cmd_args.is_empty() {
                let _ = Command::new(&cmd_args[0])
                    .args(&cmd_args[1..])
                    .status();
            }
        }
    }
}

pub fn run_exec_batch(results: &[PathBuf], opts: &Options) {
    for cmd in &opts.exec_batch_cmds {
        if cmd.args.is_empty() { continue; }

        let batch_size = if opts.batch_size == 0 { results.len().max(1) } else { opts.batch_size };

        let all_paths: Vec<String> = results.iter()
            .map(|p| format_path_for_exec(p, opts))
            .collect();

        for chunk in all_paths.chunks(batch_size) {
            let has_placeholder = cmd.args.iter().any(|a| contains_placeholder(a));

            if has_placeholder {
                let mut args = vec![cmd.args[0].clone()];
