                    if contains_placeholder(tmpl) {
                        for path_str in chunk {
                            let p = PathBuf::from(path_str);
                            let expanded = substitute_single_placeholder(tmpl, path_str, &p);
                            args.push(expanded);
                        }
                    } else {
                        args.push(tmpl.clone());
                    }
                }
                if !args.is_empty() {
                    let _ = Command::new(&args[0]).args(&args[1..]).status();
                }
            } else {
                let mut args = cmd.args.clone();
                args.extend(chunk.iter().cloned());
                if !args.is_empty() {
                    let _ = Command::new(&args[0]).args(&args[1..]).status();
                }
            }
        }
    }
}

pub fn run_list_details(results: &[PathBuf], opts: &Options) {
    let paths: Vec<String> = results.iter()
        .map(|p| format_path_for_exec(p, opts))
        .collect();
    if !paths.is_empty() {
        let _ = Command::new("ls")
            .args(&["-ld", "--color=auto"])
            .args(&paths)
            .status();
    }
