/// Format a path for use in exec/exec-batch/list-details mode
/// - Adds ./ prefix for relative non-./ paths
/// - Strips trailing / from directories
pub fn format_path_for_exec(path: &Path, opts: &Options) -> String {
    let s = path.to_string_lossy().into_owned();

    // Strip trailing slash (for exec, dirs don't get trailing /)
    let s = s.trim_end_matches('/');
    let s = s.to_string();

    // Determine if we should strip the ./ prefix
    let should_strip = match opts.strip_cwd_prefix {
        StripCwdPrefix::Always => true,
        StripCwdPrefix::Never => false,
        StripCwdPrefix::Auto => false,
    };

    if should_strip {
        if let Some(stripped) = s.strip_prefix("./") {
            return stripped.to_string();
        }
        return s;
    }

    // Add ./ prefix for relative paths
    if !s.starts_with('/') && !s.starts_with("./") && !s.starts_with("../") {
        format!("./{}", s)
    } else {
        s
    }
}

fn contains_placeholder(s: &str) -> bool {
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '{' && i + 1 < chars.len() {
            if chars[i + 1] == '{' {
                i += 2;
                continue;
            }
            let mut j = i + 1;
            while j < chars.len() && chars[j] != '}' {
                j += 1;
            }
            if j < chars.len() {
                let placeholder: String = chars[i+1..j].iter().collect();
                match placeholder.as_str() {
                    "" | "/" | "//" | "." | "/." => return true,
                    _ => {}
                }
            }
        } else if chars[i] == '}' && i + 1 < chars.len() && chars[i + 1] == '}' {
            i += 2;
            continue;
        }
        i += 1;
    }
    false
}

fn substitute_placeholders(tmpl_args: &[String], path_str: &str, path: &Path) -> Vec<String> {
    let has_placeholder = tmpl_args.iter().any(|a| contains_placeholder(a));

    if has_placeholder {
        tmpl_args.iter()
            .map(|a| substitute_single_placeholder(a, path_str, path))
            .collect()
    } else {
        let mut args = tmpl_args.to_vec();
        args.push(path_str.to_string());
        args
    }
}

pub fn substitute_single_placeholder(tmpl: &str, path_str: &str, path: &Path) -> String {
    let basename = path.file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| {
            // path_str might be "." or something without filename
            path_str.trim_end_matches('/').to_string()
        });

    let parent = {
        // Get parent of the path (stripping trailing /)
        let p_str = path_str.trim_end_matches('/');
        if let Some(last_slash) = p_str.rfind('/') {
            let parent_part = &p_str[..last_slash];
            if parent_part.is_empty() { "/".to_string() } 
            else { parent_part.to_string() }
        } else {
            ".".to_string()
        }
    };

    let path_no_ext = remove_extension_from_path(path_str, &basename);
    let basename_no_ext = remove_extension_from_basename(&basename);

    let chars: Vec<char> = tmpl.chars().collect();
    let mut result = String::new();
    let mut i = 0;

    while i < chars.len() {
        if chars[i] == '{' {
            if i + 1 < chars.len() && chars[i + 1] == '{' {
                result.push('{');
                i += 2;
                continue;
            }
            let mut j = i + 1;
            while j < chars.len() && chars[j] != '}' {
                j += 1;
            }
            if j < chars.len() {
                let placeholder: String = chars[i+1..j].iter().collect();
                match placeholder.as_str() {
                    "" => result.push_str(path_str),
                    "/" => result.push_str(&basename),
                    "//" => result.push_str(&parent),
                    "." => result.push_str(&path_no_ext),
                    "/." => result.push_str(&basename_no_ext),
                    _ => {
                        result.push('{');
                        result.push_str(&placeholder);
                        result.push('}');
                    }
                }
                i = j + 1;
            } else {
                result.push(chars[i]);
                i += 1;
            }
        } else if chars[i] == '}' && i + 1 < chars.len() && chars[i + 1] == '}' {
            result.push('}');
            i += 2;
        } else {
            result.push(chars[i]);
            i += 1;
        }
    }

    result
}

fn remove_extension_from_path(path_str: &str, basename: &str) -> String {
    // Remove trailing / first
    let path_str = path_str.trim_end_matches('/');
    let basename = basename.trim_end_matches('/');

    if let Some(dot_pos) = basename.rfind('.') {
        if dot_pos > 0 {
            if path_str.ends_with(basename) {
                let path_len = path_str.len();
                let ext_len = basename.len() - dot_pos;
                return path_str[..path_len - ext_len].to_string();
            }
        }
    }
    path_str.to_string()
}

fn remove_extension_from_basename(basename: &str) -> String {
    let basename = basename.trim_end_matches('/');
    if let Some(dot_pos) = basename.rfind('.') {
        if dot_pos > 0 {
            return basename[..dot_pos].to_string();
        }
    }
    basename.to_string()
}
