// Pure Rust standard library implementation of fd 10.3.0

#![allow(dead_code, unused_variables, unused_imports)]

use std::io::{self, Write, BufWriter};
use std::path::{Path, PathBuf};
use std::process;

mod args;
mod regex_impl;
mod glob_impl;
mod ignore;
mod ls_colors;
mod walk;
mod exec;

use args::*;
use exec::substitute_single_placeholder;

fn main() {
    let raw_args: Vec<String> = std::env::args().collect();
    match args::parse(raw_args) {
        ParseResult::Ok(opts) => {
            let exit_code = run_search(opts);
            process::exit(exit_code);
        }
        ParseResult::Error(msg) => {
            eprintln!("{}", msg);
            process::exit(1);
        }
        ParseResult::Help(long) => {
            if long {
                print_long_help();
            } else {
                print_short_help();
            }
            process::exit(0);
        }
        ParseResult::Version => {
            println!("fd {}", VERSION);
            process::exit(0);
        }
    }
}

const VERSION: &str = "10.3.0";

fn run_search(opts: Options) -> i32 {
    let results = walk::collect_results(&opts);

    if opts.quiet {
        return if results.is_empty() { 1 } else { 0 };
    }

    if opts.list_details {
        exec::run_list_details(&results, &opts);
        return 0;
    }

    if !opts.exec_cmds.is_empty() {
        exec::run_exec(&results, &opts);
        return 0;
    }

    if !opts.exec_batch_cmds.is_empty() {
        exec::run_exec_batch(&results, &opts);
        return 0;
    }

    // Regular output
    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());

    let use_color = match opts.color {
        ColorMode::Always => true,
        ColorMode::Never => false,
        ColorMode::Auto => is_tty(),
    };

    let use_color = use_color && std::env::var("NO_COLOR").is_err();

    let ls_colors = if use_color {
        ls_colors::LsColors::from_env()
    } else {
        ls_colors::LsColors::empty()
    };

    for path in &results {
        let display_str = if let Some(ref fmt) = opts.format {
            let path_for_exec = exec::format_path_for_exec(path, &opts);
            substitute_single_placeholder(fmt, &path_for_exec, path)
        } else if opts.print0 {
            // For print0: add ./ prefix but keep trailing / for dirs
            let s = path.to_string_lossy().into_owned();
            match opts.strip_cwd_prefix {
                StripCwdPrefix::Always => {
                    s.strip_prefix("./").map(|x| x.to_string()).unwrap_or(s)
                }
                _ => {
                    if !s.starts_with('/') && !s.starts_with("./") && !s.starts_with("../") {
                        format!("./{}", s)
                    } else {
                        s
                    }
                }
            }
        } else {
            path.to_string_lossy().into_owned()
        };

        if use_color {
            let colored = ls_colors.colorize(path, &display_str);
            if opts.print0 {
                write!(out, "{}\0", colored).ok();
            } else {
                writeln!(out, "{}", colored).ok();
            }
        } else {
            if opts.print0 {
                write!(out, "{}\0", display_str).ok();
            } else {
                writeln!(out, "{}", display_str).ok();
            }
        }
    }

    0
}

