// fd - A simple, fast and user-friendly alternative to find
// Pure Rust standard library implementation of fd 10.3.0

#![allow(dead_code, unused_variables, unused_imports)]

use std::io::{self, Write, BufWriter};
use std::path::{Path, PathBuf};
use std::process;

mod args;
mod regex_impl;
mod glob_impl;
mod ignore;
mod ls_colors;
mod walk;
mod exec;

use args::*;
use exec::substitute_single_placeholder;

fn main() {
    let raw_args: Vec<String> = std::env::args().collect();
    match args::parse(raw_args) {
        ParseResult::Ok(opts) => {
            let exit_code = run_search(opts);
            process::exit(exit_code);
        }
        ParseResult::Error(msg) => {
            eprintln!("{}", msg);
            process::exit(1);
        }
