# Let me now look at the color issue for the main problem:
# The issue is not just the extension mapping but also the PATH COLORING
# For "a/foo.txt", the path prefix "a/" should be colored with dir color
# and the filename "foo.txt" colored with its own color

# Let me look at the colorize function in ls_colors.rs
# The key issue: for a path like "a/foo.txt", I need to:
# 1. Find the parent directory "a/"  
# 2. Color "a/" with dir color
# 3. Color "foo.txt" with its file color

# Let me update the colorize function in ls_colors.rs to handle this

cat > /tmp/fix_colors.py << 'EOF'
with open('/workspace/fd-impl/src/ls_colors.rs', 'r') as f:
    content = f.read()

old = """    pub fn colorize(&self, path: &Path, display: &str) -> String {
        // Get the actual file metadata (symlink_metadata to detect symlinks)
        let meta = path.symlink_metadata().ok();

        if let Some(ref m) = meta {
            let ft = m.file_type();

            // Check special types first
            if ft.is_symlink() {
                return apply_color(display, &self.link_color, &self.reset);
            }

            if ft.is_dir() {
                return colorize_dir(display, &self.dir_color, &self.reset);
            }

            if ft.is_socket() {
                return apply_color(display, &self.socket_color, &self.reset);
            }
            if ft.is_fifo() {
                return apply_color(display, &self.fifo_color, &self.reset);
            }
            if ft.is_block_device() {
                return apply_color(display, &self.block_color, &self.reset);
            }
            if ft.is_char_device() {
                return apply_color(display, &self.char_color, &self.reset);
            }

            if ft.is_file() {
                // Check if executable FIRST
                let perms = m.permissions().mode();
                if perms & 0o111 != 0 {
                    if let Some(ref code) = self.exec_color {
                        return apply_color_code(display, code, &self.reset);
                    }
                    // If no exec_color, fall through to extension
                }

                // Get the path's filename for name lookup
                let name = path.file_name()
                    .map(|n| n.to_string_lossy().into_owned())
                    .unwrap_or_default();

                // Check special filenames
                if let Some(color) = self.name_colors.get(&name) {
                    return apply_color_code(display, color, &self.reset);
                }

                // Check extension
                if let Some(ext) = path.extension() {
                    let ext_lower = ext.to_string_lossy().to_lowercase();
                    if let Some(color) = self.ext_colors.get(&ext_lower) {
                        return apply_color_code(display, color, &self.reset);
                    }
                }
            }
        }

        display.to_string()
    }"""

new = """    pub fn colorize(&self, path: &Path, display: &str) -> String {
        // Get the actual file metadata (symlink_metadata to detect symlinks)
        let meta = path.symlink_metadata().ok();

        if let Some(ref m) = meta {
            let ft = m.file_type();

            // Check special types first
            if ft.is_symlink() {
                // For symlinks, check if there's a parent path to colorize
                return self.colorize_with_parent(display, &apply_color_string(display, &self.link_color, &self.reset));
            }

            if ft.is_dir() {
                return colorize_dir(display, &self.dir_color, &self.reset);
            }

            if ft.is_socket() {
                return self.colorize_with_parent(display, &apply_color_string(display, &self.socket_color, &self.reset));
            }
            if ft.is_fifo() {
                return self.colorize_with_parent(display, &apply_color_string(display, &self.fifo_color, &self.reset));
            }
            if ft.is_block_device() {
                return self.colorize_with_parent(display, &apply_color_string(display, &self.block_color, &self.reset));
            }
            if ft.is_char_device() {
                return self.colorize_with_parent(display, &apply_color_string(display, &self.char_color, &self.reset));
            }

            if ft.is_file() {
                let file_color = self.get_file_color(path, m);

                if let Some(code) = file_color {
                    // For paths with parent directories, color the parent dir parts
                    let file_name = path.file_name()
                        .map(|n| n.to_string_lossy().into_owned())
                        .unwrap_or_else(|| display.to_string());

                    return self.colorize_path_with_file_color(display, &file_name, &code);
                }

                // No file color - but still colorize parent dirs if any
                let file_name = path.file_name()
                    .map(|n| n.to_string_lossy().into_owned())
                    .unwrap_or_else(|| display.to_string());
                return self.colorize_path_prefix_only(display, &file_name);
            }
        }

        display.to_string()
    }

    fn get_file_color(&self, path: &Path, meta: &std::fs::Metadata) -> Option<String> {
        // Check if executable FIRST
        let perms = meta.permissions().mode();
        if perms & 0o111 != 0 {
            if let Some(ref code) = self.exec_color {
                return Some(code.clone());
            }
        }

        // Get the path's filename for name lookup
        let name = path.file_name()
            .map(|n| n.to_string_lossy().into_owned())
            .unwrap_or_default();

        // Check special filenames
        if let Some(color) = self.name_colors.get(&name) {
            return Some(color.clone());
        }

        // Check extension
        if let Some(ext) = path.extension() {
            let ext_lower = ext.to_string_lossy().to_lowercase();
            if let Some(color) = self.ext_colors.get(&ext_lower) {
                return Some(color.clone());
            }
        }

        None
    }

    /// Colorize a path where file has its own color and parent dirs get dir color
    fn colorize_path_with_file_color(&self, display: &str, file_name: &str, file_color: &str) -> String {
        // Find where the file name starts in display
        if let Some(last_slash) = display.rfind('/') {
            // There's a parent path - color the directory prefix and the file
            let dir_prefix = &display[..=last_slash]; // includes the /
            let name_in_display = &display[last_slash+1..];

            if let Some(ref dir_code) = self.dir_color {
                format!("\x1b[{}m{}\x1b[0m\x1b[{}m{}\x1b[0m",
                    dir_code, dir_prefix, file_color, name_in_display)
            } else {
                format!("{}\x1b[{}m{}\x1b[0m",
                    dir_prefix, file_color, name_in_display)
            }
        } else {
            // No parent - just color the file
            format!("\x1b[{}m{}\x1b[0m", file_color, display)
        }
    }

    /// Colorize only the parent directory part, leaving filename uncolored
    fn colorize_path_prefix_only(&self, display: &str, file_name: &str) -> String {
        if let Some(last_slash) = display.rfind('/') {
            let dir_prefix = &display[..=last_slash];
            let name_in_display = &display[last_slash+1..];
            if let Some(ref dir_code) = self.dir_color {
                format!("\x1b[{}m{}\x1b[0m{}", dir_code, dir_prefix, name_in_display)
            } else {
                display.to_string()
            }
        } else {
            display.to_string()
        }
    }

    /// Colorize the file portion (already colored) within a path with dir-colored prefix
    fn colorize_with_parent(&self, display: &str, colored_name: &str) -> String {
        display.to_string()
    }"""

content = content.replace(old, new)

with open('/workspace/fd-impl/src/ls_colors.rs', 'w') as f:
    f.write(content)
print("Done")
EOF
