        let regex = SimpleRegex::parse(pattern)?;
        Ok(Pattern { regex, case_insensitive })
    }

    pub fn is_match(&self, text: &str) -> bool {
        let text = if self.case_insensitive {
            text.to_lowercase()
        } else {
            text.to_string()
        };
        self.regex.is_match(&text)
    }"""

new = """    pub fn new(pattern: &str, case_insensitive: bool) -> Result<Self, String> {
        let pattern = if case_insensitive {
            pattern.to_lowercase()
        } else {
            pattern.to_string()
        };
        let regex = SimpleRegex::parse(&pattern)?;
        Ok(Pattern { regex, case_insensitive })
    }

    pub fn is_match(&self, text: &str) -> bool {
        let text = if self.case_insensitive {
            text.to_lowercase()
        } else {
            text.to_string()
        };
        self.regex.is_match(&text)
    }"""

content = content.replace(old, new)

with open('/workspace/fd-impl/src/regex_impl.rs', 'w') as f:
    f.write(content)
print("Done")
EOF
