        path
    } else {
        abs_path = std::env::current_dir().unwrap().join(path);
        abs_path.as_path()
    };
    println!("path: {}", path.display());
    let meta = path.symlink_metadata();
    match meta {
        Ok(m) => println!("is_symlink: {}", m.file_type().is_symlink()),
        Err(e) => println!("error: {}", e),
    }
}
