    /// Load ignore files from parent directories (above search root)
    /// This implements the default fd behavior of respecting parent gitignore files
    pub fn load_parent_ignore_files(&mut self, search_root: &Path, no_ignore_parent: bool) {
        if no_ignore_parent {
            return;
        }

        // Walk up from search root to filesystem root, collecting ignore files
        // They should be applied in order from root to search_root
        let mut parent_rules = Vec::new();

        if let Some(mut parent) = search_root.parent() {
            loop {
                if parent.as_os_str().is_empty() || parent == std::path::Path::new("/") {
                    // Load root level gitignore if any
                    if self.respect_gitignore && (self.in_git_repo || !self.require_git) {
                        let gi = parent.join(".gitignore");
                        if gi.exists() {
                            if let Some(rules) = IgnoreRules::from_file(&gi) {
                                parent_rules.push(rules);
                            }
                        }
                    }
                    break;
                }

                if self.respect_gitignore && (self.in_git_repo || !self.require_git) {
                    let gi = parent.join(".gitignore");
                    if gi.exists() {
                        if let Some(rules) = IgnoreRules::from_file(&gi) {
                            parent_rules.push(rules);
                        }
                    }
                }
                if self.respect_ignore {
                    let ig = parent.join(".ignore");
                    if ig.exists() {
                        if let Some(rules) = IgnoreRules::from_file(&ig) {
                            parent_rules.push(rules);
                        }
                    }
                }
                if self.respect_fdignore {
                    let fdi = parent.join(".fdignore");
                    if fdi.exists() {
                        if let Some(rules) = IgnoreRules::from_file(&fdi) {
                            parent_rules.push(rules);
                        }
                    }
                }

                match parent.parent() {
                    Some(p) => parent = p,
                    None => break,
                }
            }
        }

        // Reverse to apply from root to parent
        parent_rules.reverse();

        // Insert parent rules at the beginning (before search root rules)
        let mut new_rules = parent_rules;
        new_rules.append(&mut self.rule_sets);
        self.rule_sets = new_rules;
    }"""

